namespace Lru;

/// <summary>Parses one command line and applies it to an <see cref="LruCache"/>.</summary>
public static class CommandProcessor
{
    public static void Execute(LruCache cache, ReadOnlySpan<char> line, TextWriter output)
    {
        ArgumentNullException.ThrowIfNull(cache);
        ArgumentNullException.ThrowIfNull(output);

        int space = line.IndexOf(' ');
        ReadOnlySpan<char> command = space < 0 ? line : line[..space];
        ReadOnlySpan<char> args = space < 0 ? [] : line[(space + 1)..];

        switch (command)
        {
            case "SET":
                int split = args.IndexOf(' ');
                if (split > 0)
                {
                    cache.Set(args[..split], args[(split + 1)..]);
                }

                break;
            case "GET":
                output.WriteLine(cache.TryGet(args, out string value) ? value : "NULL");
                break;
            case "DEL":
                output.WriteLine(cache.Remove(args) ? "1" : "0");
                break;
            case "SIZE":
                output.WriteLine(cache.Count);
                break;
            default:
                // Blank or unrecognised lines produce no output.
                break;
        }
    }
}

namespace Lru;

/// <summary>
/// A fixed-capacity least-recently-used cache with O(1) expected-time operations.
/// Entries live in a pre-sized array forming an intrusive doubly linked list (most recent at the head),
/// indexed by a dictionary from key to slot.
/// </summary>
public sealed class LruCache
{
    private const int None = -1;

    private struct Entry
    {
        public string Key;
        public string Value;
        public int Prev;
        public int Next;
    }

    private readonly int _capacity;
    private readonly Dictionary<string, int> _index;
    private readonly Dictionary<string, int>.AlternateLookup<ReadOnlySpan<char>> _lookup;
    private readonly Entry[] _entries;
    private int _head = None;
    private int _tail = None;
    private int _freeHead = None;
    private int _used;

    public LruCache(int capacity)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(capacity, 1);
        _capacity = capacity;
        _index = new Dictionary<string, int>(capacity + 1, StringComparer.Ordinal);
        _lookup = _index.GetAlternateLookup<ReadOnlySpan<char>>();
        _entries = new Entry[capacity];
    }

    public int Count => _index.Count;

    public void Set(ReadOnlySpan<char> key, ReadOnlySpan<char> value)
    {
        if (_lookup.TryGetValue(key, out int slot))
        {
            _entries[slot].Value = value.ToString();
            MoveToFront(slot);
            return;
        }

        if (_index.Count == _capacity)
        {
            // Reuse the least recently used slot for the new key.
            slot = _tail;
            _index.Remove(_entries[slot].Key);
            Unlink(slot);
        }
        else
        {
            slot = AllocateSlot();
        }

        string keyString = key.ToString();
        _entries[slot].Key = keyString;
        _entries[slot].Value = value.ToString();
        _index.Add(keyString, slot);
        LinkAtFront(slot);
    }

    public bool TryGet(ReadOnlySpan<char> key, out string value)
    {
        if (_lookup.TryGetValue(key, out int slot))
        {
            MoveToFront(slot);
            value = _entries[slot].Value;
            return true;
        }

        value = string.Empty;
        return false;
    }

    public bool Remove(ReadOnlySpan<char> key)
    {
        if (!_lookup.Remove(key, out _, out int slot))
        {
            return false;
        }

        Unlink(slot);
        _entries[slot] = new Entry { Key = null!, Value = null!, Prev = None, Next = _freeHead };
        _freeHead = slot;
        return true;
    }

    private int AllocateSlot()
    {
        if (_freeHead != None)
        {
            int slot = _freeHead;
            _freeHead = _entries[slot].Next;
            return slot;
        }

        return _used++;
    }

    private void MoveToFront(int slot)
    {
        if (slot == _head)
        {
            return;
        }

        Unlink(slot);
        LinkAtFront(slot);
    }

    private void LinkAtFront(int slot)
    {
        ref Entry e = ref _entries[slot];
        e.Prev = None;
        e.Next = _head;
        if (_head != None)
        {
            _entries[_head].Prev = slot;
        }
        else
        {
            _tail = slot;
        }

        _head = slot;
    }

    private void Unlink(int slot)
    {
        ref Entry e = ref _entries[slot];
        if (e.Prev != None)
        {
            _entries[e.Prev].Next = e.Next;
        }
        else
        {
            _head = e.Next;
        }

        if (e.Next != None)
        {
            _entries[e.Next].Prev = e.Prev;
        }
        else
        {
            _tail = e.Prev;
        }

        e.Prev = None;
        e.Next = None;
    }
}

using System.Globalization;
using System.Text;
using Lru;

const int BufferSize = 1 << 16;

var encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false);
using var input = new StreamReader(Console.OpenStandardInput(), encoding, detectEncodingFromByteOrderMarks: false, BufferSize);
using var output = new StreamWriter(Console.OpenStandardOutput(), encoding, BufferSize) { AutoFlush = false, NewLine = "\n" };

string? header = input.ReadLine();
if (header is null || !int.TryParse(header.AsSpan().Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out int capacity) || capacity < 1)
{
    return 0;
}

var cache = new LruCache(capacity);
string? line;
while ((line = input.ReadLine()) is not null)
{
    CommandProcessor.Execute(cache, line.AsSpan().TrimEnd('\r'), output);
}

output.Flush();
return 0;
